[IO.File]::WriteAllText((Join-Path $PWD 'site/token.txt'), "tok-7f3a9c`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/api/orders.json'), "[{`"id`":1,`"total`":40}]`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/token.txt'), "tok-7f3a9c`n")
[IO.File]::WriteAllText((Join-Path $PWD 'login-then-call.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The client's flow: log in with Basic to fetch a token, then call the API with it as a`n# Bearer token. Usage: sh login-then-call.sh <base URL> <user:password>`nbase=`$1`ntoken=`$(curl -sSf --cacert server.pem -u `"`$2`" `"`${base}token.txt`") || exit `$?`ncurl -sSf --cacert server.pem --oauth2-bearer `"`$token`" `"`${base}api/orders.json`"`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--user', 'app:s3cret', '--user', ':tok-7f3a9c', 'https://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh login-then-call.sh https://127.0.0.1:8080/ app:s3cret } finally { Stop-Process $server0 }
